import { api, isMockMode } from '../lib/api.js';
import { escapeHtml, money, shortDate } from '../lib/format.js';
import { icon, setTitle, toast } from '../lib/dom.js';

const nav = [
  ['/admin', 'Overview', '01'], ['/admin/events', 'Events', '02'], ['/admin/orders', 'Orders', '03'],
  ['/admin/exceptions', 'Needs attention', '04'], ['/admin/tickets', 'Tickets', '05'],
  ['/admin/staff', 'Door staff', '06'], ['/admin/exports', 'Exports', '07'],
];

export async function adminView(path) {
  setTitle('Box office');
  if (!isMockMode && !await api.getSession()) return adminLogin();
  const data = await api.adminData();
  const section = sectionFor(path, data);
  return {
    meta: { section: 'admin' },
    html: `<main id="main" class="ops" tabindex="-1">
      <aside class="ops-nav">
        <div class="ops-user"><span>AO</span><div><strong>Ada / Admin</strong><small>All events</small></div></div>
        <nav aria-label="Box office sections">${nav.map(([href, label, number]) => `<a href="${href}" data-link ${path === href ? 'aria-current="page"' : ''}><span>${number}</span>${label}${href === '/admin/exceptions' && data.metrics.exceptions ? `<b>${data.metrics.exceptions}</b>` : ''}</a>`).join('')}</nav>
        ${isMockMode ? '<button type="button" class="ops-reset" data-reset-demo>Reset demo data</button>' : ''}
      </aside>
      <div class="ops-content">
        <header class="ops-head"><div><p class="kicker">TIXORA / BOX OFFICE</p><h1>${section.title}</h1><p>${section.note}</p></div>${section.action || ''}</header>
        ${section.html}
      </div>
      <dialog class="event-dialog" data-event-dialog></dialog>
    </main>`,
    mount() {
      wireAdmin(data, path);
    },
  };
}

function adminLogin() {
  return {
    meta: { section: 'admin' },
    html: `<main id="main" class="ops-login" tabindex="-1"><section><p class="kicker">BOX OFFICE / STAFF ONLY</p><h1>Sign in before the doors open.</h1><p>Administrator and event staff access is checked by Supabase Auth.</p><form data-admin-login><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><div class="form-error" data-login-error hidden></div><button class="button button--ink button--wide">Sign in ${icon('arrow')}</button></form></section></main>`,
    mount() {
      const form = document.querySelector('[data-admin-login]');
      form.addEventListener('submit', async (event) => {
        event.preventDefault(); const button = form.querySelector('button'); const errorBox = form.querySelector('[data-login-error]');
        button.disabled = true; errorBox.hidden = true;
        try { const values = new FormData(form); await api.signIn(values.get('email'), values.get('password')); window.dispatchEvent(new PopStateEvent('popstate')); }
        catch (error) { errorBox.textContent = error.message; errorBox.hidden = false; button.disabled = false; }
      });
    },
  };
}

function sectionFor(path, data) {
  if (path === '/admin/events') return eventsSection(data);
  if (path === '/admin/orders') return ordersSection(data, false);
  if (path === '/admin/exceptions') return ordersSection(data, true);
  if (path === '/admin/tickets') return ticketsSection(data);
  if (path === '/admin/staff') return staffSection(data);
  if (path === '/admin/exports') return exportsSection(data);
  return overviewSection(data);
}

function overviewSection(data) {
  const latest = [...data.orders].sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt)).slice(0, 5);
  return {
    title: 'Today at the box office', note: 'The numbers that need a decision, without the dashboard theatre.',
    action: '<a class="button button--ink" href="/admin/events" data-link>Manage events →</a>',
    html: `<section class="metric-ledger" aria-label="Sales summary">
      <div><span>Gross collected</span><strong>${money(data.metrics.revenueMinor, { compact: true })}</strong><small>Verified payments</small></div>
      <div><span>Tickets sold</span><strong>${data.metrics.sold.toLocaleString('en-NG')}</strong><small>Across ${data.events.length} events</small></div>
      <div><span>Checked in</span><strong>${data.metrics.checkedIn}</strong><small>Recorded scans</small></div>
      <div class="${data.metrics.exceptions ? 'metric-ledger__warning' : ''}"><span>Needs attention</span><strong>${data.metrics.exceptions}</strong><small>Paid, not fulfilled</small></div>
    </section>
    ${data.metrics.exceptions ? `<a class="exception-strip" href="/admin/exceptions" data-link>${icon('warning')}<span><strong>${data.metrics.exceptions} paid order needs a person.</strong><small>A late transfer arrived after its inventory hold expired.</small></span>${icon('arrow')}</a>` : ''}
    <section class="ops-section"><div class="ops-section__head"><div><p class="kicker">LIVE INVENTORY</p><h2>Published events</h2></div><a href="/admin/events" data-link>Open event book →</a></div>
      <div class="event-ledger">${data.events.map(eventLedger).join('')}</div>
    </section>
    <section class="ops-section"><div class="ops-section__head"><div><p class="kicker">LATEST ACTIVITY</p><h2>Orders</h2></div><a href="/admin/orders" data-link>See every order →</a></div>${ordersTable(latest)}</section>`,
  };
}

function eventsSection(data) {
  return {
    title: 'Events', note: 'Artwork, prices, fees and capacity live here.',
    action: '<button class="button button--ink" type="button" data-new-event>+ New event</button>',
    html: `<section class="ops-section ops-section--flush"><div class="event-book">${data.events.map((event, index) => `
      <article class="event-book__row" style="--event-accent:${event.accent}">
        <span class="event-book__index">${String(index + 1).padStart(2, '0')}</span>
        <img src="${event.image}" alt="">
        <div><span class="status-label status-label--${event.status === 'published' ? 'live' : 'pending'}">${event.status}</span><h2>${escapeHtml(event.name)}</h2><p>${shortDate(event.startsAt)} · ${escapeHtml(event.venue)}</p></div>
        <div class="event-book__inventory"><strong>${event.tiers.reduce((sum, tier) => sum + tier.sold, 0)}</strong><span>sold</span><strong>${event.tiers.reduce((sum, tier) => sum + tier.remaining, 0)}</strong><span>left</span></div>
        <div class="event-book__tiers">${event.tiers.map((tier) => `<span>${escapeHtml(tier.name)} <b>${money(tier.priceMinor)}</b></span>`).join('')}</div>
        <button type="button" class="icon-button" data-edit-event="${event.id}" aria-label="Edit ${escapeHtml(event.name)}">${icon('edit')}</button>
      </article>`).join('')}</div></section>`,
  };
}

function ordersSection(data, exceptionsOnly) {
  const orders = exceptionsOnly ? data.orders.filter((order) => order.fulfillmentStatus === 'paid_exception') : data.orders;
  return {
    title: exceptionsOnly ? 'Needs attention' : 'Orders',
    note: exceptionsOnly ? 'Money arrived, but no ticket was issued. Resolve these before routine work.' : 'Payment and fulfilment remain separate so nothing gets hidden.',
    action: `<label class="table-search">${icon('search')}<input type="search" placeholder="Search orders" data-table-search></label>`,
    html: `${exceptionsOnly && orders.length ? `<div class="exception-explainer"><strong>${icon('warning')} ${orders.length} payment exception</strong><p>Late bank transfer after a hold expired. Capacity was not exceeded. Record a manual refund or fulfil only after inventory becomes available.</p></div>` : ''}<section class="ops-section ops-section--flush" data-order-table>${ordersTable(orders, true)}</section>`,
  };
}

function ticketsSection(data) {
  return {
    title: 'Tickets', note: 'Search the human number, attendee or event. Reissue never revives the old QR.',
    action: `<label class="table-search">${icon('search')}<input type="search" placeholder="Ticket or attendee" data-table-search></label>`,
    html: `<section class="ops-section ops-section--flush"><div class="data-table-wrap"><table class="data-table" data-filter-table><thead><tr><th>Ticket</th><th>Attendee</th><th>Event / tier</th><th>Issued</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.tickets.map((ticket) => {
      const event = data.events.find((item) => item.id === ticket.eventId);
      const tier = event?.tiers.find((item) => item.id === ticket.tierId);
      return `<tr><td><strong>${escapeHtml(ticket.number)}</strong></td><td>${escapeHtml(ticket.attendeeName)}<small>${escapeHtml(ticket.attendeeEmail)}</small></td><td>${escapeHtml(event?.name || '')}<small>${escapeHtml(tier?.name || '')}</small></td><td>${shortDate(ticket.issuedAt)}</td><td>${status(ticket.status)}</td><td>${ticket.status === 'void' ? '—' : `<button class="table-action" type="button" data-ticket-action="${ticket.id}">Void / reissue</button>`}</td></tr>`;
    }).join('')}</tbody></table></div></section>`,
  };
}

function staffSection(data) {
  return {
    title: 'Door staff', note: 'Scanner access follows event assignment, not a hidden menu item.',
    action: '<button class="button button--ink" type="button" data-invite-staff>+ Invite staff</button>',
    html: `<section class="ops-section ops-section--flush"><div class="staff-list">${data.staff.map((staff) => `<article><span class="avatar">${staff.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><div><h2>${escapeHtml(staff.name)}</h2><p>${escapeHtml(staff.email)}</p></div><div class="assignment-list">${staff.events.map((eventId) => `<span>${escapeHtml(data.events.find((event) => event.id === eventId)?.name || '')}</span>`).join('')}</div>${status(staff.status)}<button class="icon-button" aria-label="Edit ${escapeHtml(staff.name)}">${icon('edit')}</button></article>`).join('')}</div></section>`,
  };
}

function exportsSection(data) {
  return {
    title: 'Exports', note: 'A reconciliation file should answer a question, not create another spreadsheet cleanup job.',
    action: '',
    html: `<section class="export-sheet"><div><p class="kicker">EVENT RECONCILIATION</p><h2>Tickets, attendees and payment state</h2><p>One row per attendee. Formula-like text is escaped before download.</p></div><label>Event<select data-export-event><option value="all">All events</option>${data.events.map((event) => `<option value="${event.id}">${escapeHtml(event.name)}</option>`).join('')}</select></label><button class="button button--ink" data-export-csv>${icon('download')} Download CSV</button></section>
    <section class="export-note"><span>INCLUDED COLUMNS</span><p>Event, tier, order reference, payment state, purchaser, attendee, ticket number, ticket state, issued time, check-in time, price, booking fee and order total.</p></section>`,
  };
}

function eventLedger(event) {
  const sold = event.tiers.reduce((sum, tier) => sum + tier.sold, 0);
  const total = event.tiers.reduce((sum, tier) => sum + tier.capacity, 0);
  const pct = total ? Math.round((sold / total) * 100) : 0;
  return `<article><div class="event-ledger__date">${shortDate(event.startsAt)}</div><div><strong>${escapeHtml(event.name)}</strong><span>${escapeHtml(event.venue)}</span></div><div class="inventory-rule"><span style="width:${pct}%;--bar:${event.accent}"></span></div><div><strong>${sold} / ${total}</strong><span>${pct}% sold</span></div><a href="/event/${event.slug}" data-link aria-label="Open ${escapeHtml(event.name)}">${icon('arrow')}</a></article>`;
}

function ordersTable(orders, detailed = false) {
  if (!orders.length) return '<div class="empty-ledger"><strong>No matching orders.</strong><p>When a buyer begins checkout, the order appears here.</p></div>';
  return `<div class="data-table-wrap"><table class="data-table" data-filter-table><thead><tr><th>Order</th><th>Buyer</th><th>Event / tier</th><th>Total</th><th>Payment</th><th>Fulfilment</th>${detailed ? '<th>Action</th>' : ''}</tr></thead><tbody>${orders.map((order) => `<tr><td><strong>${escapeHtml(order.displayReference)}</strong><small>${shortDate(order.createdAt)}</small></td><td>${escapeHtml(order.buyer.fullName)}<small>${escapeHtml(order.buyer.email)}</small></td><td>${escapeHtml(order.eventName || '')}<small>${order.quantity} × ${escapeHtml(order.tierName || '')}</small></td><td><strong>${money(order.pricing.totalMinor)}</strong></td><td>${status(order.paymentStatus)}</td><td>${status(order.fulfillmentStatus)}</td>${detailed ? `<td><button class="table-action" type="button" data-order-action="${order.id}" data-exception="${order.fulfillmentStatus === 'paid_exception'}">${order.fulfillmentStatus === 'paid_exception' ? 'Resolve' : 'Open'}</button></td>` : ''}</tr>`).join('')}</tbody></table></div>`;
}

function status(value) {
  const labels = { paid: 'Paid', pending: 'Pending', fulfilled: 'Fulfilled', paid_exception: 'Needs attention', checked_in: 'Checked in', issued: 'Issued', void: 'Void', voided: 'Closed', refunded: 'Refunded', active: 'Active', failed: 'Failed' };
  return `<span class="status-label status-label--${value}">${labels[value] || value}</span>`;
}

function wireAdmin(data, path) {
  document.querySelector('[data-reset-demo]')?.addEventListener('click', () => {
    if (confirm('Reset all purchases and check-ins made in this browser?')) { api.reset(); window.location.reload(); }
  });
  const input = document.querySelector('[data-table-search]');
  input?.addEventListener('input', () => {
    const query = input.value.trim().toLowerCase();
    document.querySelectorAll('[data-filter-table] tbody tr').forEach((row) => { row.hidden = !row.textContent.toLowerCase().includes(query); });
  });
  document.querySelectorAll('[data-edit-event]').forEach((button) => button.addEventListener('click', () => openEventDialog(data.events.find((event) => event.id === button.dataset.editEvent))));
  document.querySelector('[data-new-event]')?.addEventListener('click', () => openNewEventDialog());
  document.querySelector('[data-invite-staff]')?.addEventListener('click', () => openStaffDialog(data.events));
  document.querySelectorAll('[data-ticket-action]').forEach((button) => button.addEventListener('click', () => openTicketDialog(data.tickets.find((ticket) => ticket.id === button.dataset.ticketAction))));
  document.querySelector('[data-export-csv]')?.addEventListener('click', () => exportCsv(data, document.querySelector('[data-export-event]').value));
  document.querySelectorAll('[data-order-action]').forEach((button) => button.addEventListener('click', async () => {
    if (button.dataset.exception !== 'true') return toast('This sandbox keeps the order summary in the table. Search by reference to reconcile it.', 'info');
    if (!confirm('Record that this exception was manually refunded in Paystack? This does not call the Paystack refund API.')) return;
    button.disabled = true;
    try { await api.resolveException(button.dataset.orderAction); toast('Manual refund recorded and exception closed.', 'success'); window.dispatchEvent(new PopStateEvent('popstate')); }
    catch (error) { toast(error.message, 'error'); button.disabled = false; }
  }));
}

function openEventDialog(event) {
  const dialog = document.querySelector('[data-event-dialog]');
  const feeValue = event.fee.mode === 'percentage' ? event.fee.bps / 100 : (event.fee.fixedMinor || 0) / 100;
  dialog.innerHTML = `<form method="dialog" data-event-form>
    <header><div><p class="kicker">EDIT EVENT / ${escapeHtml(event.code)}</p><h2>${escapeHtml(event.name)}</h2></div><button class="icon-button" value="cancel" aria-label="Close">${icon('close')}</button></header>
    <div class="dialog-scroll">
      <div class="dialog-fields">
        <div class="field-pair"><label>Event name<input name="name" value="${escapeHtml(event.name)}" required></label><label>Status<select name="status"><option value="draft" ${event.status === 'draft' ? 'selected' : ''}>Draft</option><option value="published" ${event.status === 'published' ? 'selected' : ''}>Published</option><option value="closed" ${event.status === 'closed' ? 'selected' : ''}>Closed</option></select></label></div>
        <label>Venue<input name="venue" value="${escapeHtml(event.venue)}" required></label>
        <div class="field-pair"><label>Starts at<input name="startsAt" type="datetime-local" value="${event.startsAt.slice(0, 16)}" required></label><label>Accent color<input name="accent" type="color" value="${event.accent}"></label></div>
        <div class="field-pair"><label>Fee mode<select name="feeMode"><option value="none">No fee</option><option value="fixed_order" ${event.fee.mode === 'fixed_order' ? 'selected' : ''}>Fixed per order</option><option value="fixed_ticket" ${event.fee.mode === 'fixed_ticket' ? 'selected' : ''}>Fixed per ticket</option><option value="percentage" ${event.fee.mode === 'percentage' ? 'selected' : ''}>Percentage</option></select></label><label>Fee value <small>NGN or percentage</small><input name="feeValue" type="number" min="0" step="0.01" value="${feeValue}"></label></div>
      </div>
      <section class="tier-editor"><div class="tier-editor__head"><div><p class="kicker">TICKET INVENTORY</p><h3>Tiers</h3></div><button class="button button--outline" type="button" data-add-tier>+ Add tier</button></div><div data-tier-editor>${event.tiers.map(tierEditorRow).join('')}</div></section>
    </div>
    <footer><button class="button button--outline" value="cancel">Cancel</button><button class="button button--ink" type="submit" value="save">Save event & tiers</button></footer>
  </form>`;
  dialog.showModal();
  dialog.querySelector('[data-add-tier]').addEventListener('click', () => {
    dialog.querySelector('[data-tier-editor]').insertAdjacentHTML('beforeend', tierEditorRow({ id: '', name: '', code: '', description: '', priceMinor: 0, capacity: 50, sold: 0, maxPerOrder: 6, status: 'active' }));
  });
  dialog.querySelector('[data-event-form]').addEventListener('submit', async (submitEvent) => {
    submitEvent.preventDefault();
    const values = new FormData(submitEvent.currentTarget);
    const feeMode = values.get('feeMode'); const number = Number(values.get('feeValue'));
    const fee = feeMode === 'percentage' ? { mode: feeMode, bps: Math.round(number * 100) } : feeMode === 'none' ? { mode: 'none' } : { mode: feeMode, fixedMinor: Math.round(number * 100) };
    const tiers = [...dialog.querySelectorAll('.tier-editor-row')].map((row) => ({
      id: row.dataset.id || undefined, name: row.querySelector('[data-tier-name]').value, code: row.querySelector('[data-tier-code]').value,
      description: row.querySelector('[data-tier-description]').value, priceMinor: Math.round(Number(row.querySelector('[data-tier-price]').value) * 100),
      capacity: Number(row.querySelector('[data-tier-capacity]').value), maxPerOrder: Number(row.querySelector('[data-tier-max]').value), status: row.querySelector('[data-tier-status]').value,
    }));
    const button = submitEvent.currentTarget.querySelector('button[type="submit"]'); button.disabled = true;
    try {
      await api.updateEvent(event.id, { name: values.get('name'), venue: values.get('venue'), accent: values.get('accent'), status: values.get('status'), startsAt: new Date(values.get('startsAt')).toISOString(), fee });
      await api.saveTiers(event.id, tiers);
      dialog.close(); toast('Event and tier inventory saved.', 'success'); window.dispatchEvent(new PopStateEvent('popstate'));
    } catch (error) { toast(error.message, 'error'); button.disabled = false; }
  });
}

function tierEditorRow(tier) {
  return `<div class="tier-editor-row" data-id="${tier.id || ''}"><div class="tier-editor-row__line"><label>Name<input data-tier-name value="${escapeHtml(tier.name || '')}" required placeholder="e.g. VVIP"></label><label>Code<input data-tier-code value="${escapeHtml(tier.code || '')}" required maxlength="12" placeholder="VVIP"></label><label>Status<select data-tier-status><option value="active" ${tier.status === 'active' ? 'selected' : ''}>Active</option><option value="closed" ${tier.status === 'closed' ? 'selected' : ''}>Closed</option></select></label></div><label>Description<input data-tier-description value="${escapeHtml(tier.description || '')}" placeholder="What this admission includes"></label><div class="tier-editor-row__line tier-editor-row__line--numbers"><label>Price (₦)<input data-tier-price type="number" min="0" step="1" value="${Number(tier.priceMinor || 0) / 100}" required></label><label>Capacity <small>${tier.sold || 0} sold</small><input data-tier-capacity type="number" min="${tier.sold || 1}" value="${tier.capacity || 50}" required></label><label>Max / order<input data-tier-max type="number" min="1" max="50" value="${tier.maxPerOrder || 6}" required></label></div></div>`;
}

function openNewEventDialog() {
  const dialog = document.querySelector('[data-event-dialog]');
  const defaultDate = new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString().slice(0, 16);
  dialog.innerHTML = `<form method="dialog" data-new-event-form><header><div><p class="kicker">NEW EVENT / DRAFT FIRST</p><h2>Set the first bill</h2></div><button class="icon-button" value="cancel" aria-label="Close">${icon('close')}</button></header><div class="dialog-scroll"><div class="dialog-fields"><div class="field-pair"><label>Event name<input name="name" required placeholder="Event name"></label><label>Short code<input name="code" required maxlength="10" placeholder="EVT26"></label></div><label>Venue<input name="venue" required placeholder="Venue, Lagos"></label><div class="field-pair"><label>Starts at<input name="startsAt" type="datetime-local" value="${defaultDate}" required></label><label>Accent color<input name="accent" type="color" value="#E45A2A"></label></div><label>Poster treatment<select name="image"><option value="/posters/lagos-after-dark.jpg">Live music / orange</option><option value="/posters/open-air-screen.jpg">Outdoor / green</option><option value="/posters/chop-life.jpg">Food / red</option></select></label></div><section class="tier-editor"><div class="tier-editor__head"><div><p class="kicker">FIRST INVENTORY</p><h3>Opening tier</h3></div></div>${tierEditorRow({ name: 'Regular', code: 'REG', priceMinor: 1000000, capacity: 100, maxPerOrder: 6, status: 'active' })}</section></div><footer><button class="button button--outline" value="cancel">Cancel</button><button class="button button--ink" type="submit">Create draft</button></footer></form>`;
  dialog.showModal();
  dialog.querySelector('[data-new-event-form]').addEventListener('submit', async (submitEvent) => {
    submitEvent.preventDefault(); const values = new FormData(submitEvent.currentTarget); const row = dialog.querySelector('.tier-editor-row'); const button = submitEvent.currentTarget.querySelector('button[type="submit"]'); button.disabled = true;
    try {
      await api.createEvent({ name: values.get('name'), code: values.get('code'), venue: values.get('venue'), startsAt: new Date(values.get('startsAt')).toISOString(), accent: values.get('accent'), image: values.get('image'), imagePath: String(values.get('image')).split('/').pop(), status: 'draft', fee: { mode: 'none' }, tier: { name: row.querySelector('[data-tier-name]').value, code: row.querySelector('[data-tier-code]').value, description: row.querySelector('[data-tier-description]').value, priceMinor: Math.round(Number(row.querySelector('[data-tier-price]').value) * 100), capacity: Number(row.querySelector('[data-tier-capacity]').value), maxPerOrder: Number(row.querySelector('[data-tier-max]').value) } });
      dialog.close(); toast('Draft event created. Open it to add more tiers or publish.', 'success'); window.dispatchEvent(new PopStateEvent('popstate'));
    } catch (error) { toast(error.message, 'error'); button.disabled = false; }
  });
}

function openStaffDialog(events) {
  const dialog = document.querySelector('[data-event-dialog]');
  dialog.innerHTML = `<form method="dialog" data-staff-form><header><div><p class="kicker">DOOR ACCESS</p><h2>Invite staff</h2></div><button class="icon-button" value="cancel" aria-label="Close">${icon('close')}</button></header><div class="dialog-fields"><label>Full name<input name="name" required></label><label>Email<input name="email" type="email" required></label><fieldset class="event-assignments"><legend>Assigned events</legend>${events.map((event) => `<label><input type="checkbox" name="events" value="${event.id}"><span>${escapeHtml(event.name)}</span></label>`).join('')}</fieldset><p class="dialog-note">Live mode sends a Supabase Auth invitation. Demo mode records the assignment in this browser.</p></div><footer><button class="button button--outline" value="cancel">Cancel</button><button class="button button--ink" type="submit">Send invitation</button></footer></form>`;
  dialog.showModal();
  dialog.querySelector('[data-staff-form]').addEventListener('submit', async (submitEvent) => {
    submitEvent.preventDefault(); const values = new FormData(submitEvent.currentTarget); const eventIds = values.getAll('events');
    if (!eventIds.length) return toast('Assign at least one event.', 'warning');
    const button = submitEvent.currentTarget.querySelector('button[type="submit"]'); button.disabled = true;
    try { await api.inviteStaff({ name: values.get('name'), email: values.get('email'), eventIds }); dialog.close(); toast('Staff invitation and event access saved.', 'success'); window.dispatchEvent(new PopStateEvent('popstate')); }
    catch (error) { toast(error.message, 'error'); button.disabled = false; }
  });
}

function openTicketDialog(ticket) {
  const dialog = document.querySelector('[data-event-dialog]');
  dialog.innerHTML = `<form method="dialog" data-ticket-form><header><div><p class="kicker">${escapeHtml(ticket.number)}</p><h2>Void or reissue</h2></div><button class="icon-button" value="cancel" aria-label="Close">${icon('close')}</button></header><div class="dialog-fields"><p><strong>${escapeHtml(ticket.attendeeName)}</strong><br>${escapeHtml(ticket.attendeeEmail)}</p><fieldset class="action-choice"><legend>Action</legend><label><input type="radio" name="mode" value="reissue" checked><span><strong>Reissue</strong> Void this QR and create a new signed ticket. Capacity does not change.</span></label><label><input type="radio" name="mode" value="void"><span><strong>Void only</strong> Reject this QR without creating a replacement.</span></label></fieldset><label>Reason<input name="reason" required minlength="5" placeholder="Why is this ticket changing?"></label></div><footer><button class="button button--outline" value="cancel">Cancel</button><button class="button button--ink" type="submit">Confirm action</button></footer></form>`;
  dialog.showModal();
  dialog.querySelector('[data-ticket-form]').addEventListener('submit', async (submitEvent) => {
    submitEvent.preventDefault(); const values = new FormData(submitEvent.currentTarget); const button = submitEvent.currentTarget.querySelector('button[type="submit"]'); button.disabled = true;
    try { const result = await api.replaceTicket(ticket.id, values.get('mode'), values.get('reason')); dialog.close(); toast(result.replacement ? `New ticket ${result.replacement.number} issued.` : 'Ticket voided.', 'success'); window.dispatchEvent(new PopStateEvent('popstate')); }
    catch (error) { toast(error.message, 'error'); button.disabled = false; }
  });
}

function exportCsv(data, eventId) {
  const rows = [['Event', 'Tier', 'Order reference', 'Payment', 'Purchaser name', 'Purchaser email', 'Attendee', 'Attendee email', 'Ticket', 'Ticket status', 'Unit price', 'Booking fee', 'Order total']];
  data.orders.filter((order) => eventId === 'all' || order.eventId === eventId).forEach((order) => {
    const event = data.events.find((item) => item.id === order.eventId);
    const tier = event?.tiers.find((item) => item.id === order.tierId);
    order.attendees.forEach((attendee) => {
      const ticket = data.tickets.find((item) => item.attendeeId === attendee.id && item.status !== 'void') || data.tickets.find((item) => item.attendeeId === attendee.id);
      rows.push([event?.name, tier?.name, order.displayReference, order.paymentStatus, order.buyer.fullName, order.buyer.email, attendee.fullName, attendee.email, ticket?.number || '', ticket?.status || 'not_issued', order.unitPriceMinor / 100, order.pricing.feeTotalMinor / 100, order.pricing.totalMinor / 100]);
    });
  });
  const safe = (value) => { const text = String(value ?? ''); const escaped = /^[=+\-@]/.test(text) ? `'${text}` : text; return `"${escaped.replaceAll('"', '""')}"`; };
  const blob = new Blob([rows.map((row) => row.map(safe).join(',')).join('\n')], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `tixora-reconciliation-${new Date().toISOString().slice(0, 10)}.csv`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 500);
}
